events = [("스타벅스 판교", "추천", "경로 설정"), ("스타벅스 판교", "추천", "경로 설정"),
          ("이디야 서현", "추천", "닫기"), ("이디야 서현", "추천", "무시"),
          ("성심당 본점", "직접 검색", "경로 설정"), ("스타벅스 판교", "추천", "닫기")]
W = {"경로 설정": 1.0, "무시": -0.1, "닫기": -0.5}
pref = {}
for place, how, act in events:
    w = W[act] * (1.5 if how == "직접 검색" else 1.0)
    pref[place] = round(pref.get(place, 0) + w, 2)
print(sorted(pref.items(), key=lambda x: -x[1]))
# [('스타벅스 판교', 1.5), ('성심당 본점', 1.5), ('이디야 서현', -0.6)]

import random
random.seed(0)
true = {"아침:뉴스 브리핑": 0.55, "아침:음악": 0.35, "저녁:음악": 0.6, "저녁:뉴스 브리핑": 0.2}
def run(eps, T=4000):
    n, s, got = {}, {}, 0
    for t in range(T):
        ctx = "아침" if t % 2 == 0 else "저녁"
        arms = [k for k in true if k.startswith(ctx)]
        if random.random() < eps or not all(a in n for a in arms):
            a = random.choice(arms)
        else:
            a = max(arms, key=lambda k: s[k] / n[k])
        r = 1 if random.random() < true[a] else 0
        n[a] = n.get(a, 0) + 1; s[a] = s.get(a, 0) + r; got += r
    return got / T
for e in (0.0, 0.1, 1.0): print(f"eps {e}: 수락률 {run(e):.3f} (최선 0.575)")
# eps 0.0: 수락률 0.471 (최선 0.575)
# eps 0.1: 수락률 0.546 (최선 0.575)
# eps 1.0: 수락률 0.419 (최선 0.575)
